/**
 * KETER-TYPE v0.9.7 — Playwright live drive-through (real Chromium).
 *
 * Run from the repo root (after `npm run build`):
 *   node scripts/v097-playwright-smoke.mjs
 *
 * Flow (light/day theme, the theme in the user's screenshots):
 *  A. Home: the start screen shows exactly the 11 core cards in ONE
 *     grid, no historical shelves; the 4 promoted recipes are there.
 *  B. Home DOCX hub: upload 4 real .docx files (Gemara + Rashi +
 *     Tosafot + Ein Mishpat, generated by
 *     scripts/v097-make-test-docx.py); the per-file roles are
 *     auto-detected (tertiary included); import wraps them into a
 *     Vilna Shas layout with the auto-layout notice, 0 page errors.
 *  C. In the editor, open Design ("עיצוב העמוד") → "עמוד ושוליים":
 *     the full historical library (27 recipes) is still pickable
 *     there; picking one applies it.
 *  D. Fresh context: upload the Mikraot set (Chumash + Targum +
 *     Rashi); Targum auto-detects as the verse role; import wraps
 *     into a Mikraot-family layout (Chumash recipe), 0 page errors.
 *  E. Part 4 live proof — column gap: Shulchan Aruch sample
 *     (two-column book) → Design → move the column-gap slider
 *     16 → 40 → the left column's rendered `right` offset moves
 *     measurably (live page change, not a dead control).
 *  F. Part 4 live proof — footnote separator: Mussar sample
 *     (single column, footnotes) → Design → "הערות שוליים" → move
 *     the separator-width slider 25% → 90% → the rendered separator
 *     line's width grows ~3.6×.
 *
 * Screenshots: screenshots/v097/<name>.png
 * Exit code 0 = every check passed; 1 = a failure.
 * (Requires the Playwright chromium headless shell.)
 */

import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { chromium } from 'playwright';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, '..');
const DIST = path.join(ROOT, 'dist');
const SHOTS = path.join(ROOT, 'screenshots', 'v097');
fs.mkdirSync(SHOTS, { recursive: true });

// Test .docx files (generated fresh each run).
const FIXTURES = fs.mkdtempSync(path.join(os.tmpdir(), 'keter-v097-'));
const gen = spawnSync('python3', [path.join(ROOT, 'scripts', 'v097-make-test-docx.py'), FIXTURES], { encoding: 'utf8' });
if (gen.status !== 0) {
  console.error('docx generator failed:', gen.stdout, gen.stderr);
  process.exit(1);
}

let failures = 0;
let passes = 0;
function check(name, ok, detail = '') {
  if (ok) {
    passes++;
    console.log(`  PASS  ${name}${detail ? ` — ${detail}` : ''}`);
  } else {
    failures++;
    console.log(`  FAIL  ${name}${detail ? ` — ${detail}` : ''}`);
  }
}

const MIME = {
  '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css',
  '.json': 'application/json', '.png': 'image/png', '.svg': 'image/svg+xml',
  '.woff': 'font/woff', '.woff2': 'font/woff2', '.ttf': 'font/ttf',
};

const server = http.createServer((req, res) => {
  const url = new URL(req.url, 'http://localhost');
  let filePath = path.join(DIST, decodeURIComponent(url.pathname));
  if (url.pathname === '/' || !fs.existsSync(filePath) || fs.statSync(filePath).isDirectory()) {
    filePath = path.join(DIST, 'index.html');
  }
  const ext = path.extname(filePath);
  fs.readFile(filePath, (err, data) => {
    if (err) { res.writeHead(404); res.end('not found'); return; }
    res.writeHead(200, { 'content-type': MIME[ext] ?? 'application/octet-stream' });
    res.end(data);
  });
});
await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
const port = server.address().port;
const base = `http://127.0.0.1:${port}`;

async function dismissWelcome(page) {
  const welcome = page.locator('div[role="dialog"][aria-label="איך משתמשים בכתר?"]');
  if (await welcome.isVisible().catch(() => false)) {
    await page.getByRole('button', { name: 'הבנתי, מתחילים' }).click();
    await page.waitForTimeout(600);
    check('Welcome modal closes', !(await welcome.isVisible().catch(() => false)));
  }
}

/**
 * An import (hub or sample) loads the snapshot but stays on Home —
 * pre-existing App behaviour (loadProjectSnapshotIntoWorkspace does
 * not switch work mode). The editor is entered via "המשך לפרויקט
 * האחרון" in the Home banner.
 */
async function enterEditor(page) {
  const cont = page.getByRole('button', { name: 'המשך לפרויקט האחרון' });
  check('Home banner offers "continue to the last project" after import',
    await cont.isVisible().catch(() => false));
  await cont.click();
  await page.waitForTimeout(1500);
  check('editor opens (Design button visible)',
    await page.getByRole('button', { name: 'עיצוב העמוד' }).isVisible());
}

/**
 * The hub holds an import in its review queues (warnings review, then
 * uncertain-link review) until the user resolves them — by design.
 * Drive them the way a user would: accept the warnings, then keep only
 * the confident links. No-op when no queue appears.
 */
async function resolveReviewQueue(page, prefix) {
  for (let round = 0; round < 3; round++) {
    const warnings = page.getByTestId(`${prefix}-continue-warnings`);
    if (await warnings.isVisible().catch(() => false)) {
      check('warnings review appears and can be continued', true);
      await warnings.click();
      await page.waitForTimeout(1200);
      continue;
    }
    const confident = page.getByTestId(`${prefix}-confident-only`);
    if (await confident.isVisible().catch(() => false)) {
      check('uncertain-link review appears and "confident only" resolves it', true);
      await confident.click();
      await page.waitForTimeout(1500);
      continue;
    }
    break;
  }
}

async function openDesign(page) {
  await page.getByRole('button', { name: 'עיצוב העמוד' }).click();
  await page.waitForTimeout(800);
  const aside = page.locator('aside[aria-label="חלונית עיצוב העמוד"]');
  check('Design drawer opens', await aside.isVisible());
  return aside;
}

async function setRange(page, testId, value) {
  const slider = page.getByTestId(testId);
  // Use the NATIVE value setter (not el.value = ...) so React's
  // input-value tracker sees a real change and onChange fires.
  await slider.evaluate((el, v) => {
    const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
    setter.call(el, String(v));
    el.dispatchEvent(new Event('input', { bubbles: true }));
    el.dispatchEvent(new Event('change', { bubbles: true }));
  }, value);
  await page.waitForTimeout(900);
}

/** Text of the amber auto-layout notice banner (the one with the "שנה תבנית" button). */
async function autoLayoutNoticeText(page) {
  const banner = page.getByRole('button', { name: 'שנה תבנית' }).locator('..');
  if (!(await banner.isVisible().catch(() => false))) return '';
  return banner.innerText().catch(() => '');
}

const browser = await chromium.launch();
try {
  // ══ A+B+C. Vilna via the Home hub ═══════════════════════════════════
  {
    const pageErrors = [];
    const ctx = await browser.newContext({ viewport: { width: 1600, height: 1000 } });
    const page = await ctx.newPage();
    page.on('pageerror', (e) => pageErrors.push(String(e)));
    await page.goto(base + '/', { waitUntil: 'networkidle' });
    await page.waitForTimeout(1500);
    await dismissWelcome(page);

    // ── A. Start screen: exactly 11 core cards, no shelves ──────────
    const coreGrid = page.getByTestId('new-project-form-home-core-layouts');
    const coreCount = await coreGrid.locator('> button').count();
    check('Home core grid shows exactly 11 cards', coreCount === 11, `got ${coreCount}`);
    for (const id of ['rav_text', 'mikraot_gedolot', 'source_top_commentary_bottom', 'two_column', 'single_column', 'yiddish_sefer', 'custom_layout']) {
      check(`core card present: ${id}`, await page.getByTestId(`new-project-form-home-layout-${id}`).isVisible());
    }
    for (const id of ['chumash-rishonim', 'mishnah-classic', 'shulchan-aruch', 'siddur']) {
      check(`promoted recipe card present: ${id}`, await page.getByTestId(`new-project-form-home-recipe-${id}`).isVisible());
    }
    check('no historical shelves on Home',
      (await page.locator('[data-testid^="new-project-form-home-recipe-group-"]').count()) === 0);
    await page.screenshot({ path: path.join(SHOTS, '00-home-core.png') });

    // ── B. Hub: 4 files, roles auto-detected, import → Vilna ─────────
    const hub = page.getByTestId('docx-hub-home');
    await hub.getByTestId('docx-hub-home-file-input').setInputFiles([
      path.join(FIXTURES, 'gemara.docx'),
      path.join(FIXTURES, 'rashi.docx'),
      path.join(FIXTURES, 'tosafot.docx'),
      path.join(FIXTURES, 'ein-mishpat.docx'),
    ]);
    await page.waitForTimeout(600);
    const roleVals = [];
    for (let i = 0; i < 4; i++) {
      roleVals.push(await hub.getByTestId(`docx-hub-home-role-${i}`).inputValue());
    }
    check('4 files staged, roles auto-detected (main / primary / secondary / tertiary)',
      roleVals.join(',') === 'main_source,primary_comment,secondary_comment,tertiary_comment',
      roleVals.join(','));
    const firstOpts = await hub.getByTestId('docx-hub-home-role-0').locator('option').allTextContents();
    check('role dropdown offers 6 roles incl. tertiary + verse',
      firstOpts.length === 6 && firstOpts.some(o => o.includes('שלישי')) && firstOpts.some(o => o.includes('תרגום')),
      `${firstOpts.length} options`);
    await page.screenshot({ path: path.join(SHOTS, '01-home-hub.png') });
    await hub.getByTestId('docx-hub-home-import').click();
    await page.waitForTimeout(2500);
    await resolveReviewQueue(page, 'docx-hub-home');
    check('hub resets after the reviewed import (queue gone, no double-import)',
      !(await page.getByTestId('docx-hub-home-confident-only').isVisible().catch(() => false)));
    await enterEditor(page);
    const vilnaNotice = await autoLayoutNoticeText(page);
    check('editor opens with the Vilna auto-layout notice',
      /עומד כ/.test(vilnaNotice) && /ש״ס וילנא|Vilna/.test(vilnaNotice), vilnaNotice);
    const shasBtn = page.getByRole('button', { name: 'בדיקת ש״ס' });
    check('editor opens on the Vilna book (Shas check button present)', await shasBtn.isVisible());
    await page.screenshot({ path: path.join(SHOTS, '02-vilna-editor.png') });

    // ── C. Design: full library pickable ─────────────────────────────
    const aside = await openDesign(page);
    await aside.getByRole('button', { name: 'עמוד ושוליים' }).click();
    await page.waitForTimeout(600);
    const histHeading = aside.getByText('תבניות היסטוריות — עימוד קלאסי מוכן', { exact: true });
    check('Design page-geometry tab has the historical section', await histHeading.isVisible());
    const histSection = histHeading.locator('..');
    const recipeCount = await histSection.locator('button').count();
    check('Design still lists all 27 historical recipes', recipeCount === 27, `got ${recipeCount}`);
    await page.screenshot({ path: path.join(SHOTS, '03-design-library.png') });
    // Pick one: Shulchan Aruch — proves pickability end to end.
    await histSection.getByRole('button', { name: /שולחן ערוך/ }).first().click();
    await page.waitForTimeout(1500);
    check('picking a Design recipe applies it (editor still live, no crash)',
      await shasBtn.isVisible().catch(() => false) || await page.getByText(/שולחן ערוך/).first().isVisible().catch(() => false));
    check('no page errors in the Vilna flow', pageErrors.length === 0, pageErrors.join(' | '));
    await ctx.close();
  }

  // ══ D. Mikraot via the Home hub (fresh context) ════════════════════
  {
    const pageErrors = [];
    const ctx = await browser.newContext({ viewport: { width: 1600, height: 1000 } });
    const page = await ctx.newPage();
    page.on('pageerror', (e) => pageErrors.push(String(e)));
    await page.goto(base + '/', { waitUntil: 'networkidle' });
    await page.waitForTimeout(1500);
    await dismissWelcome(page);
    const hub = page.getByTestId('docx-hub-home');
    await hub.getByTestId('docx-hub-home-file-input').setInputFiles([
      path.join(FIXTURES, 'chumash.docx'),
      path.join(FIXTURES, 'targum.docx'),
      path.join(FIXTURES, 'rashi-mikraot.docx'),
    ]);
    await page.waitForTimeout(600);
    const vals = [];
    for (let i = 0; i < 3; i++) vals.push(await hub.getByTestId(`docx-hub-home-role-${i}`).inputValue());
    check('Mikraot files auto-detected (main / verse / primary)',
      vals.join(',') === 'main_source,verse,primary_comment', vals.join(','));
    await hub.getByTestId('docx-hub-home-import').click();
    await page.waitForTimeout(2500);
    // The Rashi→verse links in this set are only 40% confident, so the
    // hub holds the import in its uncertain-link review queue (by
    // design) — resolve it the way a user would before entering.
    await resolveReviewQueue(page, 'docx-hub-home');
    check('hub resets after the reviewed import (queue gone, no double-import)',
      !(await page.getByTestId('docx-hub-home-confident-only').isVisible().catch(() => false)));
    await enterEditor(page);
    const mikraotNotice = await autoLayoutNoticeText(page);
    check('Mikraot import wraps into a Mikraot-family layout',
      /עומד כ/.test(mikraotNotice) && /חומש|מקראות/.test(mikraotNotice), mikraotNotice);
    await page.screenshot({ path: path.join(SHOTS, '04-mikraot-editor.png') });
    check('no page errors in the Mikraot flow', pageErrors.length === 0, pageErrors.join(' | '));
    await ctx.close();
  }

  // ══ E. Part 4 — column gap moves the live two-column page ══════════
  {
    const pageErrors = [];
    const ctx = await browser.newContext({ viewport: { width: 1600, height: 1000 } });
    const page = await ctx.newPage();
    page.on('pageerror', (e) => pageErrors.push(String(e)));
    await page.goto(base + '/', { waitUntil: 'networkidle' });
    await page.waitForTimeout(1500);
    await dismissWelcome(page);
    // A plain two-column book: pick the Two balanced columns core card
    // and create with the sample starter. (The Shulchan Aruch hub sample
    // applies a recipe → fixed custom-layout boxes, which the column-gap
    // control correctly does NOT move; the gap lives in two_column.)
    await page.getByTestId('new-project-form-home-layout-two_column').click();
    await page.waitForTimeout(400);
    await page.getByTestId('new-project-form-home-submit').click();
    await page.waitForTimeout(2500);
    check('editor opens on the two-column sample book',
      await page.getByRole('button', { name: 'עיצוב העמוד' }).isVisible());
    const aside = await openDesign(page);
    await aside.getByRole('button', { name: 'עמוד ושוליים' }).click();
    await page.waitForTimeout(600);
    const gapSlider = page.getByTestId('design-column-gap');
    check('column-gap slider exists in Design', await gapSlider.isVisible());
    const gapLabel = () => page.getByTestId('design-column-gap-value').innerText();
    const startLabel = await gapLabel();
    const startVal = parseInt(startLabel, 10);
    check('column-gap starts at a sane value (fresh two-column default is 16pt)',
      Number.isFinite(startVal) && startVal >= 6 && startVal <= 48, startLabel);
    // Left-column cluster: line divs whose computed `right` is large.
    // (RTL: the left column sits far from the right edge; a bigger gap
    // pushes it further right, i.e. a larger `right` offset.)
    const leftClusterMedian = () => page.evaluate(() => {
      const divs = [...document.querySelectorAll('div.absolute')].filter(d => {
        const cs = getComputedStyle(d);
        return d.querySelector('span') && cs.right !== 'auto' && parseFloat(cs.right) > 0;
      });
      const rights = divs.map(d => parseFloat(getComputedStyle(d).right)).filter(v => v > 150);
      if (rights.length === 0) return -1;
      rights.sort((a, b) => a - b);
      return rights[Math.floor(rights.length / 2)];
    });
    const before = await leftClusterMedian();
    await setRange(page, 'design-column-gap', 40);
    check('column-gap value label updates to 40pt',
      (await gapLabel()).includes('40'), await gapLabel());
    const after = await leftClusterMedian();
    check('column gap →40 moves the left column on the live page',
      before > 0 && after > before, `median right-offset: ${before}px → ${after}px`);
    await page.screenshot({ path: path.join(SHOTS, '05-two-column-gap.png') });
    check('no page errors in the column-gap flow', pageErrors.length === 0, pageErrors.join(' | '));
    await ctx.close();
  }

  // ══ F. Part 4 — footnote separator width moves the live line ═══════
  {
    const pageErrors = [];
    const ctx = await browser.newContext({ viewport: { width: 1600, height: 1000 } });
    const page = await ctx.newPage();
    page.on('pageerror', (e) => pageErrors.push(String(e)));
    await page.goto(base + '/', { waitUntil: 'networkidle' });
    await page.waitForTimeout(1500);
    await dismissWelcome(page);
    // Mussar sample = running text WITH footnotes.
    await page.getByTestId('docx-hub-home-sample-mussar').click();
    await page.waitForTimeout(2000);
    await enterEditor(page);
    const aside = await openDesign(page);
    await aside.getByRole('button', { name: 'הערות שוליים' }).click();
    await page.waitForTimeout(600);
    const widthSlider = page.getByTestId('design-footnote-separator-width');
    check('footnote separator-width slider exists', await widthSlider.isVisible());
    const separatorWidth = () => page.evaluate(() => {
      const el = document.querySelector('div.absolute.border-t');
      return el ? el.getBoundingClientRect().width : -1;
    });
    const wBefore = await separatorWidth();
    check('a footnote separator line is rendered', wBefore > 0, `width=${wBefore}px`);
    if (wBefore > 0) {
      await setRange(page, 'design-footnote-separator-width', 90);
      const wAfter = await separatorWidth();
      check('separator width 25%→90% grows the rendered line ~3.6×',
        wAfter > wBefore * 2.5, `${Math.round(wBefore)}px → ${Math.round(wAfter)}px`);
    }
    await page.screenshot({ path: path.join(SHOTS, '06-footnote-separator.png') });
    check('no page errors in the separator flow', pageErrors.length === 0, pageErrors.join(' | '));
    await ctx.close();
  }
} finally {
  await browser.close();
  server.close();
}

console.log(`\nv097-playwright-smoke: ${passes} passed, ${failures} failed`);
process.exit(failures ? 1 : 0);
